SELECT FROM MARKETING_LEAD_INFO WHERE record_status = 'ACTIVE' AND lead_source = 'MANUAL' AND entry_emp_id = #{entryEmpId}
AND (cust_name LIKE CONCAT('%', #{keyword}, '%') OR unified_credit_code LIKE CONCAT('%', #{keyword}, '%') OR lead_no LIKE CONCAT('%', #{keyword}, '%'))
AND lead_status = #{status}
ORDER BY entry_time DESC, id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM MARKETING_LEAD_INFO WHERE record_status = 'ACTIVE' AND lead_source = 'MANUAL' AND entry_emp_id = #{entryEmpId}
AND (cust_name LIKE CONCAT('%', #{keyword}, '%') OR unified_credit_code LIKE CONCAT('%', #{keyword}, '%') OR lead_no LIKE CONCAT('%', #{keyword}, '%'))
AND lead_status = #{status}
